function health_score(array $v,array $records,array $appointments=[]): array {
 $score=100; $reasons=[]; $age=$v['last_service']?max(0,(int)((time()-strtotime($v['last_service']))/86400)):9999;
 if($age>365){$score-=25;$reasons[]='Service overdue by time';}elseif($age>180){$score-=12;$reasons[]='Service due soon';}
 if((int)$v['mileage']>15000){$score-=15;$reasons[]='Mileage is high since last check';}
 if(!$v['last_service']){$score-=20;$reasons[]='Add the last service date';}
 foreach($records as $r)if((int)$r['vehicle_id']===(int)$v['id']&&!empty($r['next_service_mileage'])&&(int)$v['mileage']>=(int)$r['next_service_mileage']){$score-=15;$reasons[]='Recommended service mileage reached';break;}
 // Use only the latest appointment for this vehicle so older bookings cannot stack bonuses.
 $latest=null; foreach($appointments as $a)if((int)$a['vehicle_id']===(int)$v['id']&&($latest===null||strcmp((string)$a['appointment_date'],(string)$latest['appointment_date'])>0))$latest=$a;
 if($latest){$status=$latest['status']??'';$increase=$status==='Completed'?15:0;
  if($increase>0){$score+=$increase;$reasons[]='Latest appointment is '.$status.' (+'.(int)$increase.' points)';}
  elseif(in_array($status,['Pending','Confirmed','In progress'],true))$reasons[]='Latest appointment is '.$status.'; the health score increases only after completion';
  elseif($status==='Cancelled')$reasons[]='Latest appointment was cancelled; it does not increase the score';
 }
 return [min(100,max(25,$score)),$reasons?:['No immediate service signals detected']];
}
function next_appointment_prediction(array $v,array $records,array $appointments=[]): array {
 $completed=null;
 foreach($appointments as $a)if((int)$a['vehicle_id']===(int)$v['id']&&($a['status']??'')==='Completed'&&($completed===null||strcmp((string)$a['appointment_date'],(string)$completed['appointment_date'])>0))$completed=$a;
 if(!$completed)return ['date_label'=>null,'mileage'=>null,'message'=>'A next-service suggestion will appear after an appointment for this vehicle is marked Completed.'];
 $serviceDate=substr((string)$completed['appointment_date'],0,10); $nextMileage=null; $linkedRecord=null;
 foreach($records as $r)if((int)$r['vehicle_id']===(int)$v['id']&&(int)($r['appointment_id']??0)===(int)$completed['id']&&!empty($r['service_date'])&&($linkedRecord===null||strcmp((string)$r['service_date'],(string)$linkedRecord['service_date'])>0))$linkedRecord=$r;
 if($linkedRecord){$serviceDate=(string)$linkedRecord['service_date'];if(!empty($linkedRecord['next_service_mileage']))$nextMileage=(int)$linkedRecord['next_service_mileage'];}
 $dueDate=(new DateTimeImmutable($serviceDate))->modify('+1 year'); $today=new DateTimeImmutable('today'); $mileage=(int)$v['mileage']; $mileageReached=$nextMileage!==null&&$mileage>=$nextMileage; $datePassed=$dueDate<=$today;
 $label=($mileageReached||$datePassed)?'Due now':$dueDate->format('d M Y');
 if($mileageReached)$message='The mechanic-recorded next-service mileage of '.number_format($nextMileage).' km has been reached. Book a service now.';
 elseif($nextMileage!==null)$message='Plan a service by '.$dueDate->format('d M Y').' or when the odometer reaches '.number_format($nextMileage).' km, whichever comes first.';
 elseif($datePassed)$message='The 12-month planning interval after the completed service has passed. Book the next service now.';
 else $message='Suggested 12 months after the completed service on '.date('d M Y',strtotime($serviceDate)).'. Confirm the interval with your mechanic.';
 return ['date_label'=>$label,'mileage'=>$nextMileage,'message'=>$message,'appointment_id'=>(int)$completed['id']];
}
function estimate_service_cost(string $service, ?int $year, int $mileage): array {
 $rates=['General service'=>[220,420],'Oil & filter change'=>[140,280],'Brake inspection'=>[60,130],'Tyre service'=>[100,450],'Engine diagnostics'=>[90,220],'Other repair'=>[120,650]];
 if(!isset($rates[$service]))$service='Other repair'; [$low,$high]=$rates[$service]; $age=$year?max(0,(int)date('Y')-$year):0; $factor=($age>=15?1.2:($age>=8?1.1:1.0))*($mileage>=150000?1.12:1.0);
 $low=(int)(round(($low*$factor)/5)*5); $high=(int)(round(($high*$factor)/5)*5); return ['service'=>$service,'low'=>$low,'high'=>$high,'mid'=>(int)(round((($low+$high)/2)/5)*5),'age'=>$age,'factor'=>$factor];
}
function build_service_reminders(array $vehicles,array $records,array $appointments): array {
 $out=[]; $today=new DateTimeImmutable('today'); $now=new DateTimeImmutable('now');
 foreach($vehicles as $v){$latest=null;foreach($records as $r){if((int)$r['vehicle_id']===(int)$v['id']){$latest=$r;break;}}$date=$v['last_service']?:($latest['service_date']??null);if($latest&&(!$date||$latest['service_date']>$date))$date=$latest['service_date'];
  if($date){$serviceDate=new DateTimeImmutable($date);$days=(int)$serviceDate->diff($today)->format('%r%a');$due=$serviceDate->modify('+365 days');$remaining=(int)$today->diff($due)->format('%r%a');if($days>=365)$out[]=['priority'=>'overdue','kind'=>'Time-based service','title'=>'Annual service is overdue','detail'=>'Last service was '.$days.' days ago. A 12-month interval is used as a planning reminder.','vehicle'=>$v,'link'=>'appointments'];elseif($remaining<=30)$out[]=['priority'=>'due-soon','kind'=>'Time-based service','title'=>'Annual service due soon','detail'=>'Estimated next service date: '.$due->format('d M Y').'.','vehicle'=>$v,'link'=>'appointments'];}
  else $out[]=['priority'=>'info','kind'=>'Service history','title'=>'Add service history','detail'=>'Add the last service date or a service record to enable time-based reminders.','vehicle'=>$v,'link'=>'vehicles'];
  if($latest&&!empty($latest['next_service_mileage'])){$target=(int)$latest['next_service_mileage'];$left=$target-(int)$v['mileage'];if($left<=0)$out[]=['priority'=>'overdue','kind'=>'Mileage-based service','title'=>'Recommended service mileage reached','detail'=>'Current mileage is '.number_format((int)$v['mileage']).' km; the recorded target was '.number_format($target).' km.','vehicle'=>$v,'link'=>'appointments'];elseif($left<=1000)$out[]=['priority'=>'due-soon','kind'=>'Mileage-based service','title'=>'Service mileage is approaching','detail'=>number_format($left).' km remain before the recorded target of '.number_format($target).' km.','vehicle'=>$v,'link'=>'appointments'];}
 }
 foreach($appointments as $a){if(in_array($a['status'],['Completed','Cancelled'],true))continue;$when=new DateTimeImmutable($a['appointment_date']);$days=(int)$now->diff($when)->format('%r%a');if($days<0)$priority='overdue';elseif($days<=7)$priority='upcoming';else continue;$out[]=['priority'=>$priority,'kind'=>'Workshop booking','title'=>$days<0?'Check your past-due booking':'Upcoming service booking','detail'=>$a['service_type'].' · '.$when->format('D, d M Y g:i A').' · '.ucfirst($a['status']).'.','vehicle'=>['id'=>$a['vehicle_id'],'make'=>$a['make'],'model'=>$a['model'],'plate'=>$a['plate']],'link'=>'appointments'];}
 $rank=['overdue'=>0,'due-soon'=>1,'upcoming'=>2,'info'=>3];usort($out,fn($a,$b)=>$rank[$a['priority']]<=>$rank[$b['priority']]);return $out;
}
$reminders=build_service_reminders($vehicles,$records,$appointments); $reminderCounts=['overdue'=>count(array_filter($reminders,fn($r)=>$r['priority']==='overdue')),'due-soon'=>count(array_filter($reminders,fn($r)=>$r['priority']==='due-soon')),'upcoming'=>count(array_filter($reminders,fn($r)=>$r['priority']==='upcoming'))];
$estimateData=null;$estimateVehicle=null;$estimateService=$_GET['service_type']??'General service';if($page==='estimator'&&!empty($_GET['vehicle_id'])){foreach($vehicles as $candidate)if((int)$candidate['id']===(int)$_GET['vehicle_id']){$estimateVehicle=$candidate;break;}if($estimateVehicle)$estimateData=estimate_service_cost($estimateService,$estimateVehicle['year']?(int)$estimateVehicle['year']:null,(int)$estimateVehicle['mileage']);}
