<?php elseif($page==='estimator'):?><div class="page-heading"><p>Estimate a planning range from service type, vehicle age and odometer.</p></div><section class="estimator-layout"><form class="panel form-grid estimator-form" method="get"><input type="hidden" name="page" value="estimator"><label>Vehicle<select required name="vehicle_id"><?php foreach($vehicles as $v):?><option value="<?=$v['id']?>" <?=(int)($_GET['vehicle_id']??0)===(int)$v['id']?'selected':''?>><?=h($v['make'].' '.$v['model'].' · '.$v['plate'])?></option><?php endforeach?></select></label><label>Service type<select name="service_type"><?php foreach(['General service','Oil & filter change','Brake inspection','Tyre service','Engine diagnostics','Other repair'] as $service):?><option value="<?=h($service)?>" <?=($estimateService===$service?'selected':'')?>><?=h($service)?></option><?php endforeach?></select></label><button class="btn primary">Calculate estimate</button></form><?php if($estimateData&&$estimateVehicle):?><section class="panel estimate-result"><span class="eyebrow">SMART COST ESTIMATE · RM</span><h2><?=h($estimateVehicle['make'].' '.$estimateVehicle['model'])?></h2><p><?=h($estimateService)?> · <?=number_format((int)$estimateVehicle['mileage'])?> km</p><div class="estimate-range"><div><small>Indicative range</small><strong><?=money($estimateData['low'])?> – <?=money($estimateData['high'])?></strong></div><div class="estimate-mid"><small>Planning midpoint</small><b><?=money($estimateData['mid'])?></b></div></div><div class="estimate-factors"><span>Vehicle age: <?=$estimateData['age']?$estimateData['age'].' years':'not provided'?></span><span>Vehicle mileage: <?=number_format((int)$estimateVehicle['mileage'])?> km</span></div><div class="estimate-disclaimer"><b>Prototype estimate</b><p>This is a transparent rule-based planning estimate using sample RM service bands, adjusted for vehicle age and mileage. It is not a live AI diagnosis or a workshop quote. Confirm the final price with the service provider.</p></div><a class="btn soft" href="index.php?page=appointments">Request this service →</a></section><?php elseif(!$vehicles):?><section class="panel empty">Add a vehicle before estimating service costs.</section><?php else:?><section class="panel estimate-placeholder"><div class="estimator-mark">RM</div><h3>Plan the likely cost before booking</h3><p>Choose a vehicle and service to see an indicative cost range adjusted for vehicle age and mileage.</p></section><?php endif?></section>
<?php elseif($page==='reminders'):?><div class="page-heading"><p>Reminders are generated from service dates, recorded mileage intervals and active appointments.</p></div><div class="reminder-stats"><article><span>Overdue</span><b><?=$reminderCounts['overdue']?></b></article><article><span>Due soon</span><b><?=$reminderCounts['due-soon']?></b></article><article><span>Bookings this week</span><b><?=$reminderCounts['upcoming']?></b></article></div><div class="reminder-grid"><?php foreach($reminders as $r):?><article class="panel reminder-card <?=h($r['priority'])?>"><div class="reminder-head"><span class="reminder-icon"><?=$r['priority']==='overdue'?'!':($r['priority']==='due-soon'?'◷':'✓')?></span><span class="status <?=$r['priority']==='overdue'?'pending':($r['priority']==='due-soon'?'confirmed':'completed')?>"><?=h(str_replace('-',' ',ucfirst($r['priority'])))?></span></div><span class="eyebrow"><?=h($r['kind'])?></span><h3><?=h($r['title'])?></h3><p class="reminder-vehicle"><?=h($r['vehicle']['make'].' '.$r['vehicle']['model'])?> · <?=h($r['vehicle']['plate'])?></p><p><?=h($r['detail'])?></p><a class="text-link" href="index.php?page=<?=h($r['link']==='vehicles'&&$me['role']==='mechanic'?'jobs':$r['link'])?>"><?=$r['link']==='appointments'?'View appointments →':($r['link']==='jobs'?'View assigned jobs →':'Update vehicle history →')?></a></article><?php endforeach?></div><?php if(!$reminders):?><section class="panel empty">No service reminders right now. Your recorded vehicles are on track.</section><?php endif?><p class="reminder-footnote">These are in-app reminders refreshed when this page loads; they do not send email or phone notifications. Time-based care uses a 12-month planning interval unless a mechanic records a specific service interval.</p>
<?php elseif($page==='health'):?><div class="page-heading"><p>Vehicle health estimate uses service history, mileage, service intervals, and the latest appointment linked to this vehicle. The score increases by 15 points only when that appointment is marked Completed. Other statuses do not increase it. This is a rule-based estimate, not a machine-learning diagnosis.</p></div><div class="health-grid"><?php foreach($vehicles as $v):[$score,$why]=health_score($v,$records,$appointments);$prediction=next_appointment_prediction($v,$records,$appointments);?><article class="panel health-card"><div class="health-top"><div><span class="eyebrow">VEHICLE HEALTH</span><h3><?=h($v['make'].' '.$v['model'])?></h3><small><?=h($v['plate'])?> · <?=number_format((int)$v['mileage'])?> km</small></div><div class="score-ring" style="--score:<?=$score?>"><b><?=$score?></b><small>/100</small></div></div><div class="progress wide"><span style="width:<?=$score?>%"></span></div><h4>Maintenance insights</h4><?php foreach($why as $w):?><div class="insight"><span>✳</span><?=h($w)?></div><?php endforeach?><div class="insight"><span>◷</span>Estimate based on available records; confirm concerns with a qualified mechanic.</div><section class="health-prediction"><span class="eyebrow">NEXT APPOINTMENT PREDICTION</span><strong class="prediction-date"><?=h($prediction['date_label']??'Waiting for a completed appointment')?></strong><p><?=h($prediction['message'])?></p><?php if(!empty($prediction['mileage'])):?><small>Mechanic next-service target: <?=number_format((int)$prediction['mileage'])?> km</small><?php endif?><a class="btn soft full" href="index.php?page=appointments">Plan the next appointment →</a></section></article><?php endforeach?></div><?php if(!$vehicles):?><div class="panel empty">Add a vehicle to see its health snapshot.</div><?php endif?>
<?php elseif($page==='inventory'):?><div class="page-heading"><p>Keep common workshop parts and stock levels current.</p></div><?php if($me['role']==='admin'):?><section class="panel"><div class="panel-head"><div><h3>Add or update a part</h3><p>Use an existing SKU to update that part.</p></div></div><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="part"><label>Part name<input required name="name"></label><label>SKU<input name="sku"></label><label>Quantity<input type="number" min="0" name="quantity" value="0"></label><label>Unit price (RM)<input type="number" step="0.01" min="0" name="unit_price" value="0"></label><button class="btn primary">Save part</button></form></section><?php endif?><section class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>Part</th><th>SKU</th><th>In stock</th><th>Unit price</th><th>Stock status</th></tr></thead><tbody><?php foreach($parts as $p):?><tr><td><b><?=h($p['name'])?></b></td><td><?=h($p['sku']??'—')?></td><td><?=number_format((int)$p['quantity'])?></td><td><?=money($p['unit_price'])?></td><td><span class="status <?=$p['quantity']<5?'pending':'completed'?>"><?=$p['quantity']<5?'Low stock':'In stock'?></span></td></tr><?php endforeach?></tbody></table></div><?php if(!$parts):?><div class="empty">Inventory is empty.</div><?php endif?></section>
<?php elseif($page==='accounts'):?><div class="page-heading"><p>Give every workshop teammate their own secure login.</p></div><section class="panel"><div class="panel-head"><div><h3>Create workshop account</h3><p>Public sign-up creates customer accounts. Staff access is granted by an administrator.</p></div></div><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="user"><label>Full name<input required name="name"></label><label>Email<input type="email" required name="email"></label><label>Password<input type="password" required minlength="8" name="password"></label><label>Role<select name="role"><option value="mechanic">Mechanic</option><option value="admin">Administrator</option></select></label><label>Phone<input name="phone"></label><button class="btn primary">Create account</button></form></section><section class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Phone</th><th>Joined</th></tr></thead><tbody><?php foreach($accounts as $u):?><tr><td><b><?=h($u['name'])?></b></td><td><?=h($u['email'])?></td><td><span class="status neutral"><?=h(ucfirst($u['role']))?></span></td><td><?=h($u['phone'])?></td><td><?=date('d M Y',strtotime($u['created_at']))?></td></tr><?php endforeach?></tbody></table></div></section>
<?php elseif($page==='qr'): $token=$_GET['token']??'';$q=$pdo->prepare('SELECT r.*,v.make,v.model,v.plate FROM service_records r JOIN vehicles v ON v.id=r.vehicle_id JOIN users u ON u.id=v.user_id WHERE r.public_token=? AND (?=1 OR v.user_id=? OR EXISTS(SELECT 1 FROM appointments assigned WHERE assigned.vehicle_id=v.id AND assigned.mechanic_id=?))');$q->execute([$token,$me['role']==='admin'?1:0,$uid,$uid]);$r=$q->fetch();?><div class="page-heading"><p>Shareable digital service history entry.</p></div><?php if($r):?><div class="panel qr-card"><span class="eyebrow">AUTOCARE DIGITAL RECORD</span><h2><?=h($r['make'].' '.$r['model'])?></h2><p><?=h($r['plate'])?> · <?=date('d M Y',strtotime($r['service_date']))?> · <?=number_format((int)$r['mileage'])?> km</p><div id="qrcode" class="qr-box"></div><h3><?=h($r['service_type'])?></h3><p><?=h($r['work_done'])?></p><p class="muted">Cost: <?=money($r['cost'])?></p><a class="text-link" href="index.php?page=records">← Back to service history</a></div><script src="https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js"></script><script>new QRCode(document.getElementById('qrcode'),{text:location.href,width:180,height:180,colorDark:'#17332e',colorLight:'#ffffff'});</script><?php else:?><div class="panel empty">Digital record unavailable or you do not have access to this vehicle.</div><?php endif?><?php endif?>
<footer class="footer">AutoCare · Smart vehicle care, made simple <span>Secure personal accounts · <?=h(ucfirst($me['role']))?> workspace</span></footer></main></div><script>const navSidebar=document.getElementById("appSidebar"),navToggle=document.getElementById("mobileNavToggle"),navBackdrop=document.querySelector(".mobile-nav-backdrop");function setMobileNav(open){navSidebar.classList.toggle("is-open",open);document.body.classList.toggle("mobile-nav-open",open);navToggle.setAttribute("aria-expanded",String(open));}navToggle.addEventListener("click",()=>setMobileNav(!navSidebar.classList.contains("is-open")));document.querySelectorAll("[data-nav-close]").forEach(el=>el.addEventListener("click",()=>setMobileNav(false)));document.addEventListener("keydown",e=>{if(e.key==="Escape")setMobileNav(false)});navSidebar.querySelectorAll(".nav-link").forEach(el=>el.addEventListener("click",()=>setMobileNav(false)));</script></body></html>

